skin:
#s75 .stage{background:linear-gradient(165deg,#faf7f1,#f5f1ea 60%,#efe8dc);color:#262625}
#s75 .stage::before{content:'';position:absolute;inset:0;background:radial-gradient(46% 38% at 82% 10%,#d9775712,transparent 60%);pointer-events:none}
#s75 .d-nav{background:#efe9decf;border:1px solid #e3dbcc;border-radius:12px}
#s75 .d-logo{font-weight:600;color:#b45a3c}
#s75 .d-links span{opacity:.66}#s75 .d-links span:hover{opacity:1;background:#d9775714;border-radius:7px}
#s75 .d-h{letter-spacing:-.01em}
#s75 .d-p{color:#6f675c}
#s75 .d-btn{background:#d97757;color:#fff;border-radius:11px;font-weight:500}
#s75 .d-btn:hover{background:#c96a4c}
#s75 .d-btn.ghost{background:#00000008;color:#8a5a44;border:1px solid #d9cdb8}
#s75 .d-input{background:#fffdf9;border:1px solid #e3dbcc;color:#262625;border-radius:999px}
#s75 .d-tog.onn{background:#d97757}
#s75 .d-badge{background:#d9775712;color:#a05537;border-radius:999px}
#s75 .d-prog{height:4px;background:#26262512}#s75 .d-prog i{background:#d97757}
#s75 .d-card{background:#efe9dd;border:1px solid #e3dbc9;border-radius:13px}
